              <p>{result.snippet}</p>
              <a href="#" onClick={() => actions.results.open()}>Open</a>
            </li>
          ))}
        </ul>
      ) : (
        <p>No results found</p>
      )}
      <a href="#" onClick={() => actions.nav.report()}>Report a problem</a>
    </main>
  );
}
